def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))

    # Extend each diagonal pair in both directions, stopping at the first
    # occupied cell or the edge of the grid.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                for sr, sc in ((-dr, -dc), (dr, dc)):
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        rr += sr
                        cc += sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
